VAR
    Overload_Timer : TON;
END_VAR

// Calculate 125% of rated current (41.5 A * 1.25 = 51.875 A)
// Use Overload_Timer to debounce or confirm overcurrent if needed, or set alarm directly.
// Rule says Overload_Timer is available.

Overload_Timer(IN := Motor_Current > 51.875,
               PT := T#3S);

IF Overload_Timer.Q THEN
    Overload_Alarm := TRUE;
END_IF

IF Fault_Reset AND NOT (Motor_Current > 51.875) THEN
    Overload_Alarm := FALSE;
END_IF

